INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147436', 65147436, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Analisis Peta Jalan Ekosistem Ekonomi Sirkular Kegiatan Pengembangan Ekosistem Ekonomi Sirkular Dan Green Academy', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99900000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket Dokumen', 'menyelaraskan berbagai kebijakan ekonomi sirkular serta mengoptimalkan implementasinya di tingkat nasional dan daerah sesuai dengan dokumen RPJMN 2025-2029 dan Rencana Kerja Tahun 2026 yang telah disusun', '1. Pendidikan minimal sarjana (S-1) di bidang Geografi/Geografi Lingkungan/Ilmu Lingkungan; 2. Memiliki kompetensi sesuai bidang yang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan, sertifikat keahlian/teknis, dan/atau sertifikat pelatihan/kursus; 3. Memiliki pengalaman kerja minimal 3 (tiga) tahun di bidang perencanaan/pengelolaan lingkungan hidup dan implementasi program ekonomi sirkular/ sustainability/sumber daya alam/lingkungan hidup atau yang relevan, dibuktikan melaui pengalaman kerja dalam CV/portofolio; 4. Memiliki pemahaman dalam bidang pelestarian lingkungan hidup yang dibuktikan dengan jurusan perkuliahan yang sesuai, serta pernah terlibat dalam penulisan karya ilmiah di bidang lingkungan hidup setidaknya 1 kali dalam 2 tahun terakhir. 5. Memiliki keterampilan dalam analisis data, baik tabular maupun spasial, serta cakap dalam presentasi dan penulisan laporan yang dibuktikan dengan pengalaman bekerja di dalam bidang tersebut yang tercantum dalam CV/portofolio. 6. Memiliki kemampuan dan pengalaman dalam mengumpulkan dan mengolah data yang dihasilkan dari kegiatan Focus Group Discussion (FGD) dan observasi lapangan yang dibuktikan melalui pengalaman kerja dalam CV/portofolio; 7. Menguasai dan terampil dalam mengoperasikan komputer, terutama Microsoft Office (Word, Excel, Power Point) dan/atau ArcGIS merupakan nilai tambah;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1961769);
