INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147454', 65147454, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN KONTEN MULTIMEDIA  PADA KEGIATAN KOORDINASI STRATEGIS PERENCANAAN DAN PENGEMBANGAN GEOPARK SUB KEGIATAN SINKRONISASI, MONITORING, DAN EVALUASI IMPLEMENTASI RENCANA AKSI NASIONAL PENGEMBANGAN  GEOPARK', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 67980000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Lingkup pekerjaan Jasa Konsultan Junior Penyusunan Konten Multimedia dalam pelaksanaan Kegiatan Koordinasi Strategis Perencanaan dan Pengembangan Geopark sub Kegiatan Sinkronisasi, Monitoring, dan Evaluasi Implementasi Rencana Aksi Nasional Pengembangan Geopark ini adalah: 1. Melakukan proses pengumpulan data dan informasi dan publikasi social media dalam bentuk foto, tulisan, dan video terkait kegiatan geopark. 2. Menyusun profil kawasan-kawasan Geopark dalam bentuk survey lapangan, dan video profil. 3. Bekerjasama dengan communication officer untuk mengelola social media Rencana Aksi Nasional Pengembangan Geopark. 4. Mendukung pelaksanaan kegiatan lainnya di lingkup Direktorat Sumber Daya energi Mineral dan Pertambangan. 5. Melaporkan hasil pekerjaan secara berkala dan menyusun laporan akhir pelaksanaan kegiatan.', 'a. Memiliki pendidikan Sarjana Strata Satu (S1) Ilmu Komunikasi. b. Memiliki pengalaman paling kurang 2 (dua) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara. c. Memiliki pengalaman kerja minimal 2 (dua) tahun bekerja pada instansi atau perusahaan yang berkaitan dengan pengembangan Kawasan Geopark, dibuktikan dengan dibuktikan dengan data pada CV dan dokumen lain yang setara. d. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara. e. Memiliki kemampuan dalam menyusun perencanaan media sosial. f. Dapat melakukan editing foto dan/atau video untuk media visual. g. Memiliki pengalaman mengkoordinasikan dan keprotokolan kegiatan acara. h. Mempunyai pengalaman dan kemampuan bekerja mandiri dan bekerja sebagai bagian dari tim yang dibuktikan dengan kontrak kerja sebelumnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1961789);
