INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147453', 65147453, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN POLICY BRIEF REKOMENDASI PENGEMBANGAN HILIRISASI KOMODITAS STRATEGIS LINGKUP PANGAN DAN PERTANIAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 84666000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Jasa Jasa Konsultan Junior Penyusunan Policy Brief Rekomendasi Pengembangan Hilirisasi Komoditas Strategis Lingkup Pangan Dan Pertanian akan terlibat dalam berbagai kegiatan meliputi: Mengumpulkan dan menganalisis data komoditas strategis, serta benchmarking dan analisis perbandingan terhadap pengembangan hilirisasi komoditas pertanian di tingkat nasional dan global. Subkeluaran: Data dasar komoditas strategis. Identifikasi wilayah sentra produksi komoditas prioritas. Melakukan kajian kebijakan dan regulasi yang mempengaruhi pengembangan hilirisasi komoditas strategis lingkup pangan dan pertanian. Subkeluaran: Pemetaan intervensi program dan kebijakan lintas K/L. Melaksanakan analisis isu strategis, tantangan, dan peluang dalam pengembangan hilirisasi komoditas, mencakup aspek budidaya, pengolahan, dan pemasaran. Subkeluaran: Analisis isu strategis hilirisasi (budidaya, pengolahan, pemasaran). Identifikasi kebutuhan pendukung (lahan, infrastruktur, industri). Menyusun assessment terhadap kesenjangan (gap analysis) antara kondisi eksisting dan target pengembangan jangka panjang dan menengah. Subkeluaran: Pemetaan target pengembangan hilirisasi jangka menengah nasional. Analisis kesenjangan (gap) jangka menengah nasional. Mendokumentasikan hasil pengumpulan data dan analisis dalam bentuk laporan periodik sesuai termin kegiatan, termasuk penyusunan grafik, tabel, dan ringkasan kebijakan (policy brief). Subkeluaran: Laporan akhir dan rekomendasi kebijakan lintas sektor. Melakukan dan mengikuti tugas dalam lingkup Direktorat Pangan dan Pertanian terkait dengan Hilirisasi Komoditas Strategis. Subkeluaran: Pemetaan stakeholder dan rancangan pembentukan serta rencana kerja satuan tugas. Dokumen pendukung koordinasi, rapat, dan penugasan teknis sesuai kebutuhan Direktorat.', 'Memiliki pendidikan minimal Sarjana (S1) pada bidang Teknik Lingkungan, atau bidang lain yang relevan dengan analisis kebijakan, pembangunan pertanian, atau pengembangan komoditas. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir atau minimal 2 (dua) tahun, baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sebagai subkontraktor, yang dibuktikan dengan data pada CV dan dokumen pendukung yang setara. Memiliki pengalaman pekerjaan di bidang pangan, pertanian, atau hilirisasi komoditas strategis (jenis pekerjaan, kompleksitas, metodologi, teknologi, atau karakteristik lainnya yang menggambarkan kesesuaian) dengan pengalaman minimal dua tahun, dibuktikan dengan CV dan dokumen pendukung yang setara. Memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang 50% (lima puluh persen) dari nilai HPS/Pagu Anggaran, dibuktikan dengan data pada CV dan dokumen pendukung yang setara. Memiliki kompetensi pendukung lainnya yang relevan dengan analisis kebijakan, pengolahan data, penyusunan laporan teknis, atau koordinasi multipihak, serta tidak mempersempit atau menujukan persyaratan kepada penyedia tertentu.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1961973);
