INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65192141', 65192141, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Perkebunan', 'Dokumen Perencanaan Sumur Dalam', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Majalengka (Kab.)', 12000000, 'April 2026', 'APBD', 1, 1, '1 paket', '1. Melaksanakan persiapan, survey lapangan, dan pengukuran. 2. Melakukan Perencanaan Teknis Sumur 3. Membuat Gambar Teknik 4. Menyusun Rencana Kerja dan Syarat (RKS) 5. Perhitungan Volume Pekerjaan 6. Menyusun Rencana Anggaran Biaya (RAB) 7. Menyusun Jadwal Pelaksanaan', '1. Persiapan terdiri dari mempersiapkan surat – surat untuk keperluan kelancaran pelaksanaan pekerjaan apabila diperlukan dan mempersiapkan tenaga ahli dan tenaga pendukung yang diperlukan. 2. Survey lapangan terdiri dari survey lokasi dan survey hidrologi. Survey Lokasi meliputi : pengecekan koordinat titik sumur, kondisi topografi, akses mobilisasi alat bor, kondisi lingkungan sekitar. Survey Hidrologi meliputi : kedalaman muka air tanah, jenis lapisan tanah/batuan, potensi akuifer, debit air tanah perkiraan, dan kualitas air tanah (biasanya data ini berasal dari data sumur sekitar dan survey geolistik jika ada) 3. Perencanaan Teknis sumur berisi desain teknis pengeboran, yang terdiri dari desain konstruksi sumur, desain sistem pompa, dan bangunan pelindung (rumah pompa) 4. Pembuatan gambar teknik terdiri dari Peta lokasi sumur, Layout area sumur, Detail konstruksi sumur dalam, Detail casing & screen, Detail rumah pompa, Instalasi perpipaan, dan Instalasi listrik pompa. 5. Penyusunan Rencana Kerja dan Syarat (RKS) berisi Metode pengeboran, Standar material casing & screen, Spesifikasi pompa air, Spesifikasi pipa, Pengujian debit (pumping test), Pengujian kualitas air, Ketentuan K3 pengeboran. 6. Perhitungan volume pekerjaan terdiri dari Perhitungan kuantitas setiap item pekerjaan, Rekapitulasi volume pekerjaan, Dasar penyusunan anggaran. 7. Penyusunan Rencana Anggaran Biaya (RAB) terdiri dari Analisa harga satuan pengeboran, Harga pompa dan instalasi, Biaya pekerjaan sipil, Total biaya pembangunan sumur dalam 8. Penyusunan Jadwal Pelaksanaan terdiri dari time schedule dan kurva S.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1962084);
