INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147438', 65147438, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN KAJIAN PERENCANAAN  WILAYAH DAN KOTA DALAM INTEGRASI PENGEMBANGAN ENERGI BERSIH DALAM PERENCANAAN KEWILAYAHAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 67980000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Lingkup pekerjaan Asisten Tenaga Ahli Bidang Perencanaan Wilayah dan Kota disusun untuk mendukung integrasi pengembangan energi bersih ke dalam perencanaan kewilayahan melalui pendekatan teknokratik dan berbasis data. Ruang lingkup ini mencakup kegiatan pengumpulan dan analisis data kewilayahan, pemantauan program pembangunan, penyusunan materi teknis, serta perumusan rekomendasi kebijakan yang bertujuan memperkuat keterpaduan antara kebijakan sektor energi dan perencanaan wilayah dan kota. Melakukan kompilasi, pengolahan, dan analisis data serta informasi kewilayahan yang diperlukan untuk penyusunan rancangan teknokratik dokumen perencanaan pembangunan dalam rangka integrasi pengembangan energi bersih. Menyusun hasil pengolahan data dan informasi terkait rencana kerja serta anggaran Kementerian/Lembaga Tahun 2026 yang mendukung pengembangan energi bersih dalam kerangka perencanaan kewilayahan. Melakukan identifikasi program pembangunan nasional yang memiliki keterkaitan dengan pengembangan energi bersih dan integrasinya ke dalam kebijakan dan dokumen perencanaan wilayah dan kota. Melaksanakan pemantauan dan evaluasi terhadap pelaksanaan program pembangunan nasional yang berhubungan dengan pengembangan energi bersih dari perspektif kewilayahan. Menyusun, mengelola, dan memastikan kesiapan materi paparan serta dokumen pendukung lainnya yang diperlukan dalam rangka pelaksanaan kegiatan pengembangan proyek energi bersih berbasis kewilayahan. Melakukan pengumpulan data lapangan melalui kunjungan ke lokasi terkait guna memperoleh informasi spasial dan non-spasial yang relevan dengan pengembangan energi bersih dalam perencanaan wilayah dan kota. Menyusun catatan, risalah, dan dokumentasi kegiatan sebagai bahan pendukung analisis dan perumusan integrasi pengembangan energi bersih dalam perencanaan kewilayahan. Menyiapkan laporan pelaksanaan kegiatan secara sistematis yang memuat hasil analisis, temuan utama, serta rekomendasi kebijakan terkait integrasi pengembangan energi bersih dalam perencanaan kewilayahan.', 'Memiliki pendidikan minimal Sarjana Strata Satu (S1) bidang Perencanaan Wilayah dan Kota; Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara. Memiliki pengalaman Pekerjaan dibidang Perencanaan Wilayah dan Kota (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan) minimal 1 tahun pengalaman dibuktikan dengan data pada CV dan dokumen lain yang setara. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara. Memiliki pemahaman yang baik terkait analisis spasial, tata ruang, dan perencanaan wilayah/kota, termasuk integrasi perencanaan sektoral dalam konteks pembangunan nasional. Menguasai perangkat lunak analisis spasial dan perencanaan, seperti GIS, pemetaan tematik, dan aplikasi pendukung perencanaan pembangunan. Memiliki pengalaman dalam penyusunan dokumen perencanaan, seperti kajian teknis, analisis keruangan, matriks sinkronisasi kebijakan, atau dokumen perencanaan pembangunan. Memiliki pengalaman dalam koordinasi kegiatan perencanaan, termasuk fasilitasi rapat, FGD, konsultasi teknis, atau pertemuan dengan lintas pemangku kepentingan. Mampu menyusun laporan teknis dan risalah pertemuan secara sistematis, sesuai standar penyusunan dokumen perencanaan pemerintah. Memahami isu-isu pembangunan energi dan transisi energi, terutama yang berkaitan dengan integrasi dalam kerangka perencanaan wilayah dan perencanaan nasional. Menguasai presentasi dan penyusunan bahan paparan, termasuk peta, infografis teknis, maupun materi visual pendukung perencanaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1962440);
