INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147421', 65147421, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN KAJIAN RENCANA INDUK GEOPARK KEGIATAN KOORDINASI STRATEGIS PERENCANAAN    DAN PENGEMBANGAN GEOPARK', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 71070000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Jasa Konsultan Junior Penyusunan Kajian Rencana Induk Geopark bertanggung jawab kepada Koordinator Sekretariat/Sekretaris Tim Pelaksana Geopark. Adapun ruang lingkup pekerjaannya adalah: Mengumpulkan data dan informasi untuk kebutuhan analisis baik dalam konteks makro maupun mikro pengempangan geopark sesuai dengan kebutuhannya; Sub keluaran: data dan informasi untuk kebutuhan analisis baik dalam konteks pengembangan geopark. Mendukung persiapan pelaksanaan kegiatan diskusi bersama stakeholders dan survei lapangan untuk mengumpulkan data; Sub keluaran: terselenggaranya diskusi dan survei lapangan terkait pengumpulan data dari stakeholders terkait. Mendukung persiapan pelaksanaan kegiatan-kegiatan diskusi terpumpun, pertemuan bilateral, dan konsultasi publik pada lokasi perencanaan; Sub keluaran: terselenggaranya kegiatan-kegiatan diskusi terpumpun, pertemuan bilateral, dan konsultasi publik pada lokasi perencanaan. Melakukan pengolahan data, analisis data, pemetaan masalah dan solusi, perumusan rencana makro dan mikro pengembangan Geopark; Sub keluaran: hasil pengolahan data terkait pemetaan masalah dan solusi, serta rumusan rencana makro dan mikro dalam pengembangan Geopark. Melakukan pengumpulan data dan analisis dalam Fasilitasi Penyusunan Rencana Induk Pengembangan Geopark; Sub keluaran: data dan hasil analisis yang berkaitan dengan fasilitasi penyusunan rencana induk pengembangan Geopark. Mendukung dalam pemetaan informasi program Kegiatan Lintas Sektor Kementerian/Lembaga, Badan Usaha, NGO, Filantropi/Donor yang dapat mendukung Pengembangan Geopark serta melakukan koordinasi dan komunikasi lintas instansi; Sub keluaran: hasil pemetaan informasi program kegiatan lintas sektor dari berbagai stakeholders yang dapat mendukung pengembangan Geopark. Melakukan peninjauan dokumen Rencana Induk Pengembangan Geopark berdasarkan pedoman penyusunan Rencana Induk Pengembangan Geopark; Sub keluaran: hasil peninjauan dokumen Rencana Induk Pengembangan Geopark. Mendukung dalam merumuskan rekomendasi substansial, strategi dan metodologi pelaksanaan perencanaan pengembangan Geopark dan penyusunan Rencana Induk Geopark yang efektif dan solutif; Sub keluaran: rumusan rekomendasi substansial dan strategi terhadap pelaksanaan perencanaan pengembangan Geopark dan rencana induk Geopark. Menyiapkan draf bahan/materi paparan dan menindaklanjuti hal substansial terkait perencanaan pengembangan Geopark; Sub keluaran: draf bahan/materi paparan terkait perencanaan pengembangan Geopark. Mendukung persiapan pelaksanaan tugas-tugas terkait koordinasi pengembangan Geopark Indonesia; Sub keluaran: dukungan kegiatan pengembangan Geopark Indonesia yang terdokumentasi. Mendukung kegiatan lainnya di lingkup Direktorat Sumber Daya Energi, Mineral dan Pertambangan yang berkaitan dengan Koordinasi Strategis Perencanaan Pengembangan Geopark; Sub keluaran: pelaksanaan dukungan kegiatan lainnya terkait koordinasi strategis perencannaan pengembangan Geopark; Melaporkan hasil pekerjaan secara berkala dan menyusun laporan akhir pelaksanaan kegiatan. Sub keluaran: laporan berkala dan laporan akhir pelaksanaan kegiatan.', 'Memiliki Pendidikan minimal Sarjana (S1) dalam bidang terkait Perencanaan Wilayah dan Kota; Memiliki pengalaman paling kurang 1 tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara; Memiliki pengalaman pekerjaan di bidang perencanaan pembangunan atau perencanaan wilayah/perencanaan pengembangan Kawasan Geopark, dibuktikan dengan surat perjanjian kerja sama, kontrak kerja dan/atau yang sejenis; Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara; Memiliki pengalaman melakukan analisis, desk review, serta mengorganisir berbagai pertemuan/diskusi/workshop, termasuk menyusun laporan yang dibuktikan dengan kontrak kerja sebelumnya; dan Mempunyai pengalaman dan kemampuan bekerja mandiri dan bekerja sebagai bagian dari tim yang dibuktikan dengan kontrak kerja sebelumnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1962641);
