INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147424', 65147424, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN KAJIAN MONITORING DAN EVALUASI RENCANA AKSI NASIONAL PENGEMBANGAN GEOPARK KEGIATAN KOORDINASI STRATEGIS PERENCANAAN  DAN PENGEMBANGAN GEOPARK', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82812000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Jasa Konsultan Junior Penyusunan Kajian Monitoring dan Evaluasi Rencana Aksi Nasional Pengembangan Geopark bertanggung jawab kepada Koordinator Sekretariat/Sekretaris Tim Pelaksana Geopark. Adapun ruang lingkup pekerjaannya adalah: Mengumpulkan data dan informasi untuk kebutuhan analisis ketercapaian Rencana Aksi Nasional Pengembangan Geopark; Subkeluaran: data dan informasi terkait ketercapaian Rencana Aksi Nasional (RAN) Pengembangan Geopark Mengorganisasi dalam pelaksanaan kegiatan diskusi dan survei lapangan untuk mengumpulkan data dan dari stakeholder; Subkeluaran: Terselenggara dan terdokumentasikannya kegiatan diskusi serta survei lapangan dengan para pemangku kepentingan Mendukung dalam Monitoring Rencana Aksi Nasional Pengembangan Geopark untuk mendapatkan gambaran ketercapaian status progres penyusunan maupun implementasi perencanaan Geopark dan identifikasi hambatan-hambatan pelaksanaan; Subkeluaran: Laporan monitoring Rencana Aksi Nasional Pengembangan Geopark Mengumpulkan data dan melakukan analisis untuk Evaluasi Rencana Aksi Nasional Pengembangan Geopark; Subkeluaran: Data dan analisis evaluasi pelaksanaan Rencana Aksi Nasional Pengembangan Geopark Mendukung dalam penyusunan Rencana Aksi Nasional Pengembangan Geopark Tahun 2025-2029; Subkeluaran: Substansi RAN Pengembangan Geopark 2025–2029 Merumuskan rekomendasi substansial, strategi dan metodologi pelaksanaan perencanaan pengembangan Geopark yang efektif dan solutif; Subkegiatan: Rekomendasi dan strategi pengembangan geopark Menyiapkan draf bahan/materi paparan dan menindaklanjuti hal substansial terkait perencanaan Geopark; Subkeluaran: Bahan paparan dan materi teknis terkait perencanaan Geopark Mendukung persiapan pelaksanaan tugas-tugas terkait koordinasi pengembangan Geopark Indonesia; Subkegiatan: Terlaksananya dukungan teknis terkait terkait koordinasi pengembangan Geopark Indonesia Mendukung kegiatan lainnya di lingkup Direktorat Sumber Daya Energi Mineral dan Pertambangan yang berkaitan dengan Kegiatan Koordinasi Strategis Perencanaan dan Pengembangan Geopark; Subkegiatan: Terlaksananya dukungan terhadap kegiatan lain di lingkup Direktorat Sumber Daya Energi Mineral dan Pertambangan Melaporkan hasil laporan akhir pelaksanaan kegiatan. Subkegiatan: Laporan Akhir Kegiatan Monitoring dan Evaluasi Rencana Aksi Nasional Pengembangan Geopark', 'Memiliki pendidikan minimal Sarjana Strata Satu (S1) Perencanaan Wilayah Kota/Ekonomi Pembangunan/Pembangunan Wilayah; Memiliki pengalaman minimal 2 (Dua) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara; Memiliki pengalaman di pemerintahan khususnya tentang sistem perencanaan pembangunan dan proses bisnisnya yang dibuktikan dengan kontrak kerja sebelumnya; Memiliki pengalaman dalam perencanaan pembangunan atau perencanaan wilayah/perencanaan pengembangan Kawasan Geopark menjadi nilai tambah yang dibuktikan data pada CV dan dokumen lain yang setara; Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara; Memiliki kemampuan desain dan pemetaan menjadi nilai tambah yang dibuktikan dengan kontrak kerja sebelumnya; Memiliki pengalaman melakukan analisis, desk review, serta mengorganisir berbagai pertemuan/diskusi/workshop, termasuk menyusun pelaporannya yang dibuktikan dengan kontrak kerja sebelumnya; dan Mempunyai pengalaman bekerja sebagai bagian dari tim dan mampu bekerja mandiri yang dibuktikan dengan kontrak kerja sebelumnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1963173);
