INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147428', 65147428, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN LAPORAN STRATEGI IMPLEMENTASI MANDATORI BAHAN BAKAR BERBASIS NABATI  KEGIATAN KOORDINASI PENGEMBANGAN PROYEK ENERGI BARU DAN TERBARUKAN DALAM TRANSISI ENERGI', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Ruang Lingkup kegiatan yang menjadi tanggung jawab Jasa Konsultan Penyusunan Strategi Implementasi Mandatori Bahan Bakar Berbasis Nabati pada Program Koordinasi Pengembangan Proyek Energi Baru dan Terbarukan dalam Transisi Energi, adalah sebagai berikut: Menganalisa kebijakan dan program kerja pemerintah terkait transisi energi baru dan terbarukan di tahun 2025; Identifikasi masalah dan hambatan dalam pelaksanaan program pemerintah terkait kebijakan Energi Baru dan Terbarukan pada implementasi mandatori bahan bakar nabati; Identifikasi peluang dan potensi dalam pelaksanaan program pemerintah terkait kebijakan Energi Baru dan Terbarukan pada implementasi mandatori bahan bakar nabati; Menyusun rekomendasi logical framework yang terdiri dari outcome - output - input untuk kebijakan terkait pemanfaatan dan pendanaan implementasi mandatori bahan bakar nabati; Monitoring program dan pemerintah pada tahun berjalan terkait transisi energi baru dan terbarukan di ranah implementasi mandatori bahan bakar nabati; Mendesain metode pengawasan dan evaluasi terhadap kebijakan pemerintah dalam bidang EBT terutama ranah implementasi mandatori bahan bakar nabati; Merancang usulan mekanisme pengendalian dan rekomendasi untuk perbaikan kebijakan dan program pemerintah terkait Energi Baru dan Terbarukan di bidang bionergi.', 'Memiliki latar belakang pendidikan minimal S1-Sains di bidang Pertanian, Biologi, Ekonomi Pertanian atau Bioteknologi dari perguruan tinggi berakreditasi A (sangat baik); Memiliki pengalaman minimal 4 (empat) tahun bekerja pada instansi atau perusahaan yang berkaitan dengan pemerintahan dan pertanian dibuktikan dengan surat perjanjian kerja sama/kontrak kerja dan/atau yang sejenis; Memiliki pemahaman yang baik tentang Energi Baru Terbarukan terutama dari Potensi produk dan hasil sampingan dari kegiatan Pertanian untuk Bahan Bakar Nabati, sistem penganggaran pemerintahan, skema pembiayaan proyek, dan manajemen proyek; Memiliki pengalaman dalam analisis data dan mampu memecahkan masalah dengan efektif dan eifisien dibuktikan dengan pengalaman kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1963350);
