INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147431', 65147431, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN POLICY BRIEF: ANALISIS SINKRONISASI DAN EFEKTIVITAS PERENCANAAN DAN KEBIJAKAN DAK TERHADAP RKP LINGKUP PANGAN DAN PERTANIAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99477858, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Melakukan penelaahan terhadap dokumen perencanaan dan kebijakan terkait RKP dan DAK, termasuk arah kebijakan, prioritas program, indikator kinerja, serta keterkaitannya dengan Renja K/L dan kebijakan sektoral pangan dan pertanian. Subkeluaran: Matriks pemetaan kebijakan dan kerangka keterkaitan RKP–DAK bidang pangan dan pertanian Melakukan pengumpulan dan analisis data dan informasi terkait alokasi, pelaksanaan, dan capaian DAK bidang pangan dan pertanian dari berbagai sumber, termasuk data statistik, laporan monev, dan informasi dari kementerian/lembaga serta pemerintah daerah. Subkeluaran: data dan ringkasan informasi pelaksanaan DAK bidang pangan dan pertanian Melakukan analisis terhadap sinkronisasi perencanaan dan kebijakan RKP dengan perencanaan dan pelaksanaan DAK, termasuk identifikasi isu strategis, permasalahan perencanaan dan penganggaran, serta tantangan implementasi di daerah. Subkeluaran: analisis sinkronisasi dan permasalahan perencanaan RKP–DAK Melakukan analisis efektivitas, efisiensi, dan keberlanjutan pelaksanaan DAK, termasuk kontribusinya terhadap capaian indikator RKP, target prioritas nasional, serta dampak terhadap pembangunan sektor pangan dan pertanian. Subkeluaran: analisis kinerja, kontribusi, dan dampak DAK terhadap RKP Berpartisipasi dalam rapat teknis, FGD, workshop, dan kegiatan koordinasi lintas sektor yang mendukung proses sinkronisasi perencanaan dan kebijakan RKP dan DAK, termasuk DAK Tematik KPPN. Subkeluaran: notulensi, bahan paparan, dan hasil kesepakatan teknis Menyusun rekomendasi kebijakan penyempurnaan perencanaan dan kebijakan DAK bidang pangan dan pertanian agar lebih selaras dan efektif dalam mendukung pencapaian prioritas RKP, serta melakukan finalisasi seluruh laporan kegiatan Subkeluaran: dokumen rekomendasi kebijakan', 'Memiliki pendidikan minimal Sarjana (S-1) bidang Agronomi dan Hortikultura; Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 3 (tiga) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara. Memiliki pengalaman Pekerjaan dibidang pertanian (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan) minimal 3 tahun pengalaman dibuktikan dengan data pada CV dan dokumen lain yang setara. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara. Menguasai substansi transfer ke daerah dan/atau sosial ekonomi pertanian yang dibuktikan dengan mengambil mata kuliah/pelatihan/bimbingan dan/atau pernah melakukan penelitian sejenis yang terkait dengan dana transfer ke daerah dan/atau sosial ekonomi pertanian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1963928);
