INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147445', 65147445, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PERANCANGAN KONTEN MEDIA DIGITAL KELAUTAN DAN  PERIKANAN  SOSIALISASI RENCANA PEMBANGUNAN BIDANG KELAUTAN DAN PERIKANAN  DIREKTORAT KELAUTAN DAN PERIKANAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Ruang Lingkup pekerjaan Jasa Konsultan Perancangan Konten Media Digital Kelautan Dan Perikanan : 1. Berkoordinasi dengan tim substansi Dit. KP dalam memetakan kebutuhan konten sesuai prioritas kebijakan kelautan dan perikanan. 2. Mengembangkan materi komunikasi dan publikasi terkait rencana pembangunan sektor kelautan dan perikanan dalam bentuk video, paparan, infografis, fakta singkat, poster digital, artikel ringan, dan konten lainnya. 3. Mengelola media sosial Dit. KP (Instagram, dan kanal lainnya), dan mendukung kampanye digital serta distribusi informasi strategis. 4. Menyediakan masukan terkait strategi komunikasi maupun visual dan peningkatan engagement publik. 5. Melaksanakan tugas tambahan yang diberikan oleh atasan langsung terkait kebutuhan konten dan publikasi', 'a. Memiliki pendidikan minimal Sarjana (S1) jurusan/program studi Sistem Informasi/Informatika/Komunikasi/Desain Komunikasi Visual. b. Memiliki pengalaman paling kurang 1 (satu) pekerjaan yang sejenis dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja. c. Pernah mempunyai kontrak dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang 50% (lima puluh persen) nilai HPS. d. Mempunyai pengalaman kerja minimal 4 (empat) tahun yang relevan di bidang pengelolaan media sosial dan pengembangan konten publikasi digital. e. Mempunyai pemahaman membuat layout, desain publikasi, dan media audio- visual.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1964017);
