INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65189800', 65189800, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Pangan Perikanan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99960000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Pangan Perikanan adalah sebagai berikut: 1. Menyusun mekanisme sinergi dan integrasi MRPN dengan pengendalian dan evaluasi program prioritas presiden bidang pangan perikanan; 2. Menyusun analisis MRPN pada bidang pangan perikanan sebagai bahan pendukung pengendalian dan evaluasi program prioritas presiden; 3. Melakukan identifikasi, analisis, validasi, dan mitigasi berdasarkan data pelaporan; 4. Menyusun laporan hasil analisis MRPN dan merumuskan usulan intervensi pengendalian pembangunan bidang pangan perikanan pada periode selanjutnya; 5. Melakukan review atas risiko pembangunan serta menyusun usulan rekomendasi kebijakan berbasis risiko untuk mendukung pencapaian sasaran program prioritas presiden bidang pangan perikanan.', 'Jasa Konsultan Junior Penyusunan Kajian Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Pangan Perikanan memiliki keluaran berupa Laporan Akhir Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Pangan Perikanan dengan waktu penyelesaian dibagi dalam 6 termin, rincian sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan pengembangan metodologi sinergi MRPN dalam pengendalian dan evaluasi Bidang Pangan Perikanan 2 Termin 2 Laporan Analisis MRPN Bidang Pangan Perikanan dalam Evaluasi Ex-Ante 3 Termin 3 Laporan Analisis MRPN Bidang Pangan Perikanan untuk Pengendalian TW I 4 Termin 4 Laporan Analisis MRPN Bidang Pangan Perikanan untuk Pengendalian TW II 5 Termin 5 Laporan Analisis MRPN Bidang Pangan Perikanan untuk Pengendalian TW III 6 Termin 6 Laporan Akhir Optimalisasi Manajemen Risiko Pembangunan Nasional sebagai Instrumen Pengendalian dan Evaluasi Pembangunan Bidang Pangan Perikanan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1964152);
