INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147422', 65147422, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN KAJIAN DUKUNGAN PENDANAAN PENGEMBANGAN GEOPARK KEGIATAN KOORDINASI STRATEGIS PERENCANAAN    DAN PENGEMBANGAN GEOPARK', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 71070000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Jasa Konsultan Junior Penyusunan Kajian Dukungan Pendanaan Pengembangan Geopark bertanggung jawab kepada Koordinator Sekretariat/Sekretaris Tim Pelaksana Geopark. Adapun ruang lingkup pekerjaannya adalah: Mengumpulkan data dan informasi untuk kebutuhan analisis dalam perencanaan pengembangan Geopark; Subkeluaran: data dan informasi untuk kebutuhan analisis dalam perencanaan pengembangan Geopark. Mendukung persiapan pelaksanaan kegiatan rapat koordinasi, forum diskusi dan survei lapangan untuk mengumpulkan data dari stakeholder; Subkeluaran: terselenggaranya rapat koordinasi, forum diskusi, dan survei lapangan untuk pengumpulan data dari stakeholder. Mendukung dalam penyusunan kebijakan Pendanaan Pengembangan Geopark untuk mendapatkan gambaran implementasi dan identifikasi hambatan-hambatan pelaksanaan; Subkeluaran: analisis kebijakan pendanaan pengembangan Geopark beserta gambaran implementasi dan hambatan pelaksanaan. Mengumpulkan data dan analisis untuk Penyusunan Alternatif Dukungan Pendanaan Pengembangan Geopark; Subkeluaran: data dan analisis untuk penyusunan alternatif dukungan pendanaan pengembangan Geopark. Mengumpulkan data dan analisis untuk pemutakhiran sub kegiatan kodefikasi Geopark; Subkeluaran: data dan analisis pemutakhiran sub kegiatan kodefikasi Geopark. Mendukung dalam merumuskan rekomendasi substansial, strategi dan metodologi pelaksanaan perencanaan pengembangan Geopark yang efektif dan solutif; Subkeluaran: rekomendasi substansial, strategi dan metodologi pelaksanaan perencanaan pengembangan Geopark. Menyiapkan draf bahan/materi paparan dan menindaklanjuti hal substansial terkait perencanaan dukungan pendanaan Geopark; Subkeluaran: draf bahan/materi terkait perencanaan dukungan pendanaan Geopark. Menyiapkan substansi buku pedoman kodefikasi sebagai panduan pendanaan Geopark di daerah; Subkeluaran: substansi buku pedoman kodefikasi sebagai panduan pendanaan Geopark di daerah. Mendukung persiapan pelaksanaan tugas-tugas terkait koordinasi pengembangan Geopark Indonesia; Subkeluaran: dukungan kegiatan koordinasi pengembangan Geopark Indonesia yang terdokumentasi. Mendukung kegiatan lainnya di lingkup Direktur Sumber Daya energi Mineral dan Pertambangan yang berkaitan dengan Kegiatan Koordinasi Strategis Perencanaan dan Pengembangan Geopark; Subkeluaran: pelaksanaan dukungan kegiatan lainnya terkait koordinasi strategis perencanaan dan pengembangan Geopark. Menyusun laporan akhir pelaksanaan kegiatan; Subkeluaran: laporan akhir pelaksanaan kegiatan.', 'Minimum Sarjana Strata Satu (S1) semua jurusan; Memiliki pengalaman paling minimal 2 (Dua) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara; Memiliki pengalaman dalam perencanaan pembangunan atau perencanaan wilayah/perencanaan pengembangan Kawasan Geopark, dibuktikan dengan surat perjanjian kerja sama, kontrak kerja dan/atau yang sejenis; Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara; Memiliki pengalaman melakukan analisis, desk review, serta membuat paparan/presentasi; Memiliki pengalaman mengorganisir dan memfasilitasi berbagai pertemuan/diskusi/lokakarya/konferensi, yang melibatkan para pihak di pemerintah dan non pemerintah; Memiliki kemampuan dalam menyusun laporan dan komunikasi yang baik; Memiliki pengalaman bekerja sebagai bagian dari tim dan mampu bekerja mandiri.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1964188);
