INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147418', 65147418, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN REKOMENDASI KOORDINASI STRATEGIS PEMBANGUNAN KAWASAN PANGAN, PERKEBUNAN, DAN PETERNAKAN DALAM MENDUKUNG PELAKSANAAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 84666000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Mengumpulkan data dan informasi gambaran umum dan karakteristik Kawasan Pangan, Perkebunan, Dan Peternakan dalam Pelaksanaan Swasembada Pangan, Energi, Dan Air. Subkeluaran: ringkasan data dan informasi lokasi pembangunan kawasan pangan, perkebunan, dan peternakan. Melakukan identifikasi potensi, peluang, serta kebutuhan pembangunan kawasan pangan, perkebunan, dan peternakan, termasuk sumber daya lahan, komoditas unggulan, infrastruktur pendukung, dan kebutuhan intervensi kebijakan. Subkeluaran: Matriks potensi, peluang, dan kebutuhan pembangunan kawasan pangan, perkebunan, dan peternakan. Melakukan identifikasi isu strategis, tantangan, dan permasalahan yang dihadapi dalam pembangunan kawasan pangan, perkebunan, dan peternakan, baik dari aspek teknis, kelembagaan, sosial, ekonomi, maupun lingkungan. Subkeluaran: analisis isu, tantangan, dan permasalahan pembangunan kawasan. Mengidentifikasi peran, kewenangan, dan keterlibatan kementerian/lembaga, pemerintah daerah, serta pemangku kepentingan lainnya dalam pembangunan kawasan pangan, perkebunan, dan peternakan. Subkeluaran: pemetaan keterlibatan stakeholder baik Kementerian/Lembaga, Badan Usaha Milik Negara/Swasta, serta Pemerintah Daerah Berpartisipasi dalam rapat teknis, Forum Group Discussion, dan kegiatan koordinasi lintas sektor yang mendukung proses pembangunan kawasan pangan, perkebunan, dan peternakan. Subkeluaran: notulensi, bahan paparan, dan hasil kesepakatan teknis. Menyusun rekomendasi kebijakan terkait koordinasi strategis pembangunan kawasan pangan, perkebunan, Dan peternakan Dalam Mendukung Pelaksanaan Swasembada Pangan, Energi, Dan Air, serta melakukan finalisasi seluruh laporan kegiatan. Subkeluaran: dokumen rekomendasi kebijakan', 'Memiliki pendidikan minimal S1 bidang pertanian yang dibuktikan dengan ijazah jenjang pendidikan terakhir. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara. Memiliki pengalaman Pekerjaan dibidang pertanian (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan) minimal 2 tahun pengalaman dibuktikan dengan data pada CV dan dokumen lain yang setara. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 2 (dua) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara. Menguasai substansi terkait budidaya pertanian/tanaman pangan/perkebunan yang dibuktikan dengan mengambil mata kuliah/pelatihan/bimbingan dan/atau pernah melakukan penelitian sejenis yang terkait.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1964345);
