INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147414', 65147414, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN KAJIAN ANALISIS   PRODUKTIVITAS DAN KESEJAHTERAAN PETANI/PETERNAK MELALUI DANA ALOKASI KHUSUS', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 84666000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Ruang Lingkup Tenaga Konsultan Junior Penyusunan Kajian Analisis Produktivitas dan Kesejahteraan Petani/Peternak melalui Dana Alokasi Khusus dalam Kegiatan Penyusunan Rencana Kerja Pemerintah (RKP) dan Dana Alokasi Khusus (DAK) Tahun 2027 LIngkup Pangan dan Pertanian meliputi: Mengidentifikasi permasalahan, tantangan, dan isu strategis Pemerintah Daerah dalam pelaksanaan Dana Alokasi Khusus lingkup Pangan dan Pertanian; Melaksanakan assesment (bersifat: rapat, focus group discussion, diskusi terbatas, wawancara, dan/atau kegiatan sejenis) terkait Dana Alokasi Khusus lingkup Pangan dan Pertanian; Mengidentifikasi dan menganalisis sebaran alokasi Dana Alokasi Khusus lingkup Pangan dan Pertanian minimal 5 tahun terakhir; Menganalisis intermediate outcome pelaksanaan Dana Alokasi Khusus lingkup Pangan dan Pertanian minimal 5 tahun terakhir; Menyusun analisis dampak Dana Alokasi Khusus lingkup Pangan dan Pertanian terhadap produktivitas dan kesejahteraan petani/peternak; Merumuskan analisis efektivitas dan efisiensi Dana Alokasi Khusus lingkup Pangan dan Pertanian di tingkat implementasi Pemerintah Daerah; Merumuskan rekomendasi implementasi Dana Alokasi Khusus lingkup Pangan dan Pertanian yang berorientasi dampak; dan Mengikuti kegiatan di lingkup Direktorat Pangan dan Pertanian yang berkaitan dengan Kegiatan Penyusunan Rencana Kerja Pemerintah (RKP) dan Dana Alokasi Khusus (DAK) Tahun 2027 Lingkup Pangan dan Pertanian.', 'Memiliki kualifikasi pendidikan minimal Sarjana (S-1) Peternakan/Pertanian; Memiliki pengalaman paling kurang 2 (tahun) pekerjaan dalam kurun waktu 2 (dua) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara; Memiliki pengalaman pekerjaan di bidang analisis transfer ke daerah (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan) minimal 2 tahun pengalaman dibuktikan dengan data pada CV dan dokumen lain yang setara; Nilai pekerjaan sejenis tertinggi dalam kurun waktu 2 (dua) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara; dan Menguasai substansi transfer ke daerah dan/atau sosial ekonomi pertanian/peternakan yang dibuktikan dengan mengambil mata kuliah/pelatihan/bimbingan dan/atau pernah melakukan penelitian sejenis yang terkait dengan dana transfer ke daerah dan/atau sosial ekonomi pertanian/peternakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1964405);
