INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147416', 65147416, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENYUSUNAN POLICY BRIEF DAN REKOMENDASI STRATEGIS SINERGI HULU-HILIR MINYAK DAN GAS BUMI UNTUK PENGUATAN KETERSEDIAAN DAN AKSES ENERGI NASIONAL', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 87756000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Ruang lingkup Kegiatan Koordinasi Strategis Sinergi Hulu-Hilir Minyak Dan Gas Bumi Dalam Menjaga Ketersediaan dan Perluasan Akses Energi Nasional meliputi: Melakukan studi literatur, pengumpulan, dan pengolahan data sekunder yang relevan untuk analisis isu strategis sinergi hulu–hilir minyak dan gas bumi, khususnya yang berkaitan dengan aspek ketersediaan (availability) dan aksesibilitas (accessibility) energi. Melakukan analisis kebijakan berdasarkan hasil studi literatur dan data sekunder untuk mengidentifikasi permasalahan, hambatan, serta opsi kebijakan dalam penguatan sinergi hulu–hilir minyak dan gas bumi. Menyusun policy brief, dan/atau dokumen rekomendasi kebijakan yang memuat analisis isu strategis, opsi kebijakan, serta rekomendasi kebijakan yang bersifat operasional sebagai bahan dukungan pengambilan keputusan. Membantu menyiapkan bahan substansi dan materi pendukung kegiatan koordinasi dan diskusi kebijakan dalam rangka penyusunan dan pemantapan rekomendasi kebijakan sinergi hulu–hilir minyak dan gas bumi.', 'Memiliki pendidikan minimal Sarjana Strata Satu (S1) pada Program Studi Perencanaan Wilayah dan Kota; Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara. Memiliki pengalaman Pekerjaan di bidang perencanaan minimal 2 (dua) tahun pengalaman dibuktikan dengan data pada CV dan dokumen lain yang setara. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara. Memiliki pengalaman dalam penyusunan Rencana Pembangunan Jangka Menengah Nasional (RPJMN) atau Masterplan Perencanaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1964932);
