INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147425', 65147425, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR “POLICY NOTES MENGENAI ANALISIS KEBIJAKAN DAN STRATEGI PERCEPATAN PROGRAM SWASEMBADA PANGAN TAHUN 2026” KEGIATAN MONITORING DAN EVALUASI PROGRAM SWASEMBADA PANGAN DALAM RPJMN 2025-2029 DAN RKP 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 84666000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( .7, Keg, @ 100000000 )', 'Ruang lingkup kegiatan Monitoring dan Evaluasi Program Prioritas Swasembada Pangan yaitu: Pemantauan dan Evaluasi Capaian Program Swasembada Pangan Melaksanakan pemantauan dan evaluasi terhadap capaian indikator, output, dan outcome kegiatan prioritas terkait swasembada pangan dalam RKP 2026 serta RPJMN 2025–2029 Analisis Efektivitas dan Sinkronisasi Program Antar-Kementerian/Lembaga Melakukan analisis terhadap efektivitas pelaksanaan program lintas K/L, serta keselarasan antara kebijakan pusat dan daerah dalam mendukung penguatan sistem pangan nasional yang berkelanjutan. Penyusunan Analisis Kebijakan dan Strategi Percepatan Swasembada Pangan Menyusun analisis kebijakan berbasis hasil evaluasi dan data untuk memperkuat strategi swasembada pangan, meningkatkan efisiensi tata kelola, dan mendorong ketahanan pangan nasional.', 'Memiliki pendidikan minimal S1 di bidang Pangan/Gizi yang dibuktikan dengan ijazah jenjang pendidikan terakhir; Memiliki pengalaman kerja minimal 2 tahun dalam bidang pangan dan pertanian, dibuktikan dalam riwayat hidup/CV; Memiliki pengalaman paling kurang 1 (satu) pekerjaan yang sejenis/mendekati dalam kurun waktu 2 (dua) tahun terakhir di lingkungan pemerintah dibuktikan dengan riwayat hidup/CV; Mempunyai pengalaman perencanaan program kerja pemerintah yang dibuktikan dengan kontrak kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1965424);
