INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65147419', 65147419, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN DOKUMEN POLICY PAPER REKOMENDASI KEBIJAKAN HOLISTIK PENGEMBANGAN PERTANIAN BERKETAHANAN IKLIM DAN RENDAH KARBON', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99477858, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Jasa Konsultan Tinjauan Komprehensif Pengembangan Pertanian Berketahanan Iklim dan Rendah Karbon ini akan terlibat dalam berbagai kegiatan meliputi: Melaksanakan analisis isu strategis, tantangan, dan peluang dalam pengembangan pertanian berketahanan iklim dan rendah karbon; Menganalisis kesenjangan kebijakan (policy gap analysis) pengembangan pertanian berketahanan iklim dan rendah karbon; Memantau dan mendokumentasikan kinerja pengembangan pertanian berketahanan iklim dan rendah karbon selama tahun anggaran 2026; Melakukan assessment/mission (fact-finding, review, dll.) insidental dan menganalisis isu strategis dari segi sosial, ekonomi, dan lingkungan dalam pengembangan pertanian berketahanan iklim dan rendah iklim; Mendokumentasikan hasil pengumpulan data dan analisis dalam bentuk laporan periodik sesuai termin kegiatan, termasuk penyusunan grafik, tabel, dan ringkasan kebijakan (policy brief); Melakukan dan mengikuti tugas dalam lingkup Direktorat Pangan dan Pertanian terkait dengan pengembangan pertanian berketahanan iklim dan rendah karbon.', 'Memiliki pendidikan minimal S1 di bidang Sains dan Teknologi Hayati yang dibuktikan dengan ijazah jenjang pendidikan terakhir; Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak dibuktikan dengan data pada CV dan dokumen lain yang setara. Memiliki pengalaman Pekerjaan penyusunan studi atau kajian di bidang pangan dan pertanian minimal 3 tahun pengalaman dibuktikan dengan data pada CV dan dokumen lain yang setara. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran yang dibuktikan dengan data pada CV dan dokumen lain yang setara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1965825);
